    tid = dlg.table.item(0, 0).text()
    out = QgsProject.instance().mapLayer(dlg._element_layer_ids.get(tid))
    renderer = out.renderer()
    assert hasattr(renderer, "categories"), "the row is not categorized"
    listed = renderer.categories()
